serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    const { action } = await req.json();

    if (action === "populate") {
      // Delete existing data
      await supabase.from("bible_reading_plan").delete().neq("dia", 0);

      // Insert all 365 days
      const dataToInsert = BIBLE_PLAN_DATA.map((day) => ({
        dia: day.dia,
        titulo: day.titulo,
        pasaje_referencia: day.lectura_1,
        pasaje_texto: `Lectura principal: ${day.lectura_1}`,
        reflexion: null,
        periodo: day.periodo.name,
        color_periodo: day.periodo.color,
        lectura_1: day.lectura_1,
        lectura_2: day.lectura_2,
        lectura_3: null,
        youtube_video_id: null,
        es_libro_narrativo: day.es_libro_narrativo,
      }));

      // Insert in batches of 50
      for (let i = 0; i < dataToInsert.length; i += 50) {
        const batch = dataToInsert.slice(i, i + 50);
        const { error } = await supabase.from("bible_reading_plan").insert(batch);
        if (error) {
          console.error(`Error inserting batch ${i}:`, error);
          throw error;
        }
      }

      return new Response(
        JSON.stringify({ success: true, message: `Inserted ${dataToInsert.length} days` }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    return new Response(
      JSON.stringify({ error: "Invalid action" }),
      { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});
